mapper.select:
select qsp.id, qsp.create_time as createTime, qspqtr.update_time as updateTime, qsp.create_user_name as createUserName, qspqtr.update_user_name as updateUserName, qsp.code, qsp.plan_type as planType, qsp.qc_level as qcLevel, qsp.major_aql as majorAql, qsp.general_aql as generalAql, qsp.remark as remark, qspqtr.id as qcTypeId, qspqtr.qc_type as qcType, qspqtr.disabled as disabled from qc_sampling_plan qsp left join qc_sampling_plan_qc_type_ref qspqtr on qsp.id = qspqtr.main_id and qspqtr.is_deleted = FALSE where ${params.sqlMap.default} AND qsp.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
qsp.create_time desc
